mapper.select:
SELECT COUNT(*)
FROM REVIEW
WHERE member_id = #{memberId}

mapper.update:
UPDATE REVIEW
SET
    rating = #{rating},
    content = #{content}
WHERE review_id = #{reviewId}
  AND member_id = #{memberId}

mapper.delete:
DELETE FROM REVIEW
WHERE review_id = #{reviewId}
  AND member_id = #{memberId}
